import { MarrowError } from '../base/errors';
import type { SkeletonInfo } from '../model/info';

/** Options for {@link generateNames}. */
export interface NamesOptions {
    /** The name of the generated type, for example `HeroNames`. */
    typeName: string;
    /** Where the skeleton came from. Named in the first line of the generated file. */
    source?: string;
}

const union = (names: readonly string[]): string =>
    names.length === 0 ? 'never' : names.map((name) => JSON.stringify(name)).join(' | ');

/**
 * Writes a TypeScript module with one type that lists every animation, skin, bone, slot and event
 * name of a skeleton. Passed to the display object, it turns a misspelled name into a compile error.
 *
 * @example
 * const source = generateNames(describeSkeleton(model), { typeName: 'HeroNames', source: 'hero.skel' });
 * // export type HeroNames = { animations: "idle" | "run"; skins: "default"; ... };
 */
export function generateNames(info: SkeletonInfo, options: NamesOptions): string {
    if (!/^[A-Za-z_$][\w$]*$/.test(options.typeName)) {
        throw new MarrowError('invalid-data', `"${options.typeName}" is not a valid type name.`, {
            fix: 'Use letters, digits, _ and $, and do not start with a digit.',
        });
    }
    const from = options.source === undefined ? '' : ` from ${options.source}`;

    return [
        `// Generated by pixi-marrow typegen${from}. Do not edit.`,
        '',
        `/** Every name in the skeleton (Spine ${info.editorVersion}). */`,
        `export type ${options.typeName} = {`,
        `    animations: ${union(info.animations.map((animation) => animation.name))};`,
        `    skins: ${union(info.skins)};`,
        `    bones: ${union(info.bones)};`,
        `    slots: ${union(info.slots)};`,
        `    events: ${union(info.events)};`,
        '};',
        '',
    ].join('\n');
}

/**
 * A type name for a skeleton file.
 *
 * @example
 * typeNameFor('art/hero-pro.skel'); // 'HeroProNames'
 */
export function typeNameFor(fileName: string): string {
    const stem = fileName.replace(/^.*[\\/]/, '').replace(/\.[^.]*$/, '');
    const words = stem.split(/[^A-Za-z0-9]+/).filter(Boolean);
    const name = words.map((word) => word.charAt(0).toUpperCase() + word.slice(1)).join('');

    return `${/^[A-Za-z]/.test(name) ? name : `Skeleton${name}`}Names`;
}
